changeSet.sql:

CREATE OR ALTER TRIGGER [metrics].[Allocation_AfterUpdate]
	ON [metrics].[Allocation]
	AFTER UPDATE
AS
BEGIN
	SET NOCOUNT ON;

	declare @action varchar(20);
	declare @state int;
	declare @oldState int;
	select @state = State from inserted;
	select @oldState = State from deleted;
	IF (@state = 3 )
	BEGIN
	  select @action = 'Delete';
	END
	Else IF(@state = 1 and @oldState = 3)
	BEGIN
		select @action = 'Add';
	END
	else
	Begin
		select @action = 'Update';
	end

	INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID])
        select @action, [queue].WriteIndexXml('', 'MetricAllocation', ID, coalesce(UpdatedBy, 0)), 'MetricAllocation', ID from inserted
END

changeSet.rollback:

	declare @action varchar(20);
	declare @state int;
	select @state = State from inserted;
	IF (@state = 3 )
	BEGIN
	  select @action = 'Delete';
	END
	else
	Begin
		select @action = 'Update';
	end

	INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID])
        select @action, [queue].WriteIndexXml('', 'MetricAllocation', ID, coalesce(UpdatedBy, 0)), 'MetricAllocation', ID from inserted
END
